String moduleInfo = """
    module full.example {
        requires some.dependency;
        exports full.example.publicapi;
        exports full.example.internal to full.example.trusted;
        opens full.example.entities;
        provides some.spi.Service with full.example.impl.ServiceImpl;
    }
    """;
System.out.println(moduleInfo);
// Kazda dyrektywa dotyczy INNEGO celu: exports (widocznosc), exports...to (widocznosc
// ograniczona), opens (refleksja), provides (rejestracja uslugi) - wszystkie moga
// wspolistniec w jednym deskryptorze bez konfliktu.

// | exports | opens | Wynik |
// |---------|-------|-------|
// | tak     | tak   | SUKCES - typ widoczny, refleksja dziala |
// | tak     | nie   | BLAD RUNTIME - InaccessibleObjectException (typ widoczny, refleksja zablokowana) |
// | nie     | tak   | BLAD KOMPILACJI - 'package is not visible' (refleksja by zadzialala, ale Main.java sie nie skompiluje z importem) |
// | nie     | nie   | BLAD KOMPILACJI - takze 'package is not visible' |
// Wniosek: exports=nie zawsze daje blad kompilacji (bo trzeba MOC zaimportowac typ zeby
// napisac kod refleksyjny na nim), niezaleznie od stanu opens.

// module tax.consumerA { requires tax.api; uses tax.TaxCalculator; }
// module tax.consumerB { requires tax.api; uses tax.TaxCalculator; }
// Dwa osobne uruchomienia:
// java --module-path <out> --add-modules tax.provider --module tax.consumerA/a.Main
// java --module-path <out> --add-modules tax.provider --module tax.consumerB/b.Main
// Obaj konsumenci niezaleznie znajduja TEGO SAMEGO dostawce (tax.provider), bo kazdy ma
// wlasna deklaracje 'uses' i wlasny graf modulow uruchomienia.

// module bad.provider { provides tax.TaxCalculator with bad.provider.NotACalculator; }
// gdzie NotACalculator NIE implementuje tax.TaxCalculator
// javac zglosi blad: error: class bad.provider.NotACalculator does not implement tax.TaxCalculator
// W odroznieniu od Lekcji 26 (plik META-INF/services, gdzie ten sam blad ujawnilby sie DOPIERO
// przy iteracji ServiceLoadera w runtime jako ServiceConfigurationError), JPMS wykrywa to JUZ
// PRZY KOMPILACJI - kolejny przyklad 'niezawodnej konfiguracji' JPMS.

java.lang.module.ModuleFinder finder = java.lang.module.ModuleFinder.of(outDir);
java.lang.module.Configuration config = ModuleLayer.boot().configuration()
    .resolve(finder, java.lang.module.ModuleFinder.of(), java.util.Set.of("reflect.target"));
ModuleLayer layer = ModuleLayer.boot().defineModulesWithOneLoader(config, ClassLoader.getSystemClassLoader());
layer.modules().forEach(m -> System.out.println(m.getName()));
// ModuleLayer pozwala zaladowac i uruchomic moduly PROGRAMOWO, w TYM SAMYM procesie JVM,
// zamiast wywolywac osobny proces java --module-path - uzywane np. przez kontenery pluginow.

