record MigrationSuggestion(String moduleName, java.util.List<String> classes, java.util.List<String> exports) {}

static java.util.List<MigrationSuggestion> analyzeForModularization(Map<String, java.util.List<String>> packageToClasses) {
    return packageToClasses.entrySet().stream()
        .map(e -> new MigrationSuggestion(e.getKey(), e.getValue(), java.util.List.of(e.getKey())))
        .toList();
}

Map<String, java.util.List<String>> pakiety = Map.of(
    "orders", java.util.List.of("Order", "OrderService"),
    "customers", java.util.List.of("Customer", "CustomerRepository"));
System.out.println("=== RAPORT MIGRACYJNY ===");
for (var s : analyzeForModularization(pakiety)) {
    System.out.println("Modul: " + s.moduleName() + ", klasy: " + s.classes() + ", exports: " + s.exports());
}

