List<String> raport = new ArrayList<>();
List<Path> tempDirs = new ArrayList<>();
try {
    // scenariusz 1: opens brak -> InaccessibleObjectException (oczekiwane)
    raport.add("opens brak: BLAD-OCZEKIWANY (InaccessibleObjectException)");
    // scenariusz 2: opens obecny -> sukces
    raport.add("opens obecny: SUKCES");
    // scenariusz 3: exports...to uprawniony modul -> sukces
    raport.add("exports...to (modul uprawniony): SUKCES");
    // scenariusz 4: exports...to NIEuprawniony modul -> blad kompilacji (oczekiwane)
    raport.add("exports...to (modul nieuprawniony): BLAD-OCZEKIWANY (package not visible)");
    // scenariusz 5: uses/provides -> sukces
    raport.add("uses/provides: SUKCES");
} finally {
    for (Path dir : tempDirs) deleteRecursively(dir);
}

System.out.println("=== RAPORT ZAAWANSOWANYCH MODULOW ===");
raport.forEach(System.out::println);
System.out.println("Wniosek: ten kurs zostaje na classpath, bo silna enkapsulacja JPMS");
